#!/bin/sh
set -eu

umask 077
base=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
mailroot=$base/Maildir

for box in accounts support general; do
    mkdir -p "$mailroot/$box/tmp" "$mailroot/$box/new" "$mailroot/$box/cur"
done

tmp=$(mktemp "$mailroot/general/tmp/.deliver.XXXXXX") || exit 1
trap '"'"'rm -f "$tmp"'"'"' 0 1 2 3 15
cat > "$tmp"

department=$(
    awk '"'"'
        function save_header(    value) {
            if (tolower(header_name) != "x-department")
                return
            value = header_value
            gsub(/^[[:space:]]+|[[:space:]]+$/, "", value)
            value = tolower(value)
            if (value == "accounts")
                is_accounts = 1
            else if (value == "support")
                is_support = 1
        }
        {
            line = $0
            sub(/\r$/, "", line)
            if (line == "") {
                save_header()
                in_body = 1
                exit
            }
            if (line ~ /^[ \t]/) {
                header_value = header_value " " line
                next
            }
            save_header()
            colon = index(line, ":")
            if (colon) {
                header_name = substr(line, 1, colon - 1)
                header_value = substr(line, colon + 1)
            } else {
                header_name = ""
                header_value = ""
            }
        }
        END {
            if (!in_body)
                save_header()
            if (is_accounts)
                print "accounts"
            else if (is_support)
                print "support"
            else
                print "general"
        }
    '"'"' "$tmp"
)

destination=$(mktemp "$mailroot/$department/tmp/.deliver.XXXXXX") || exit 1
rm -f "$destination"
mv "$tmp" "$destination"
tmp=$destination
name=$(basename "$destination" | sed '"'"'s/^\.deliver\.//'"'"')
final="$mailroot/$department/new/$(date +%s).$$.$name.$(hostname)"
mv "$tmp" "$final"
trap - 0 1 2 3 15
exit 0
