chmod 755 /srv/legacy2/mail-filter-routing/bin/deliver
chown root:root /srv/legacy2/mail-filter-routing/bin/deliver
sh -n /srv/legacy2/mail-filter-routing/bin/deliver' && stat -c '%A %U:%G %n' /srv/legacy2/mail-filter-routing/bin/deliver && sed -n '1,220p' /srv/legacy2/mail-filter-routing/bin/deliver

